631	        // Values saturate at 2^32-1
632	        let max = u32::MAX as usize;
633	        let maxxed = SubRange::new(max, max + 1).unwrap();
634	        assert_eq!(maxxed.start, maxxed.end.get());
635	        assert_eq!(SubRange::new(1 << 47, 1 << 63), Some(maxxed));
